INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Dạ vâng, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em không rõ lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, em chỉnh lại một chút, như vậy được chưa ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Giữ nụ cười, nhìn thẳng vào ống kính, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng rồi, ảnh sẽ được nhập vào hệ thống, một tuần sau là lấy được thẻ nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Thầy/cô chào ạ, em là sinh viên mới, muốn làm thẻ mượn sách thư viện ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em xuất trình thẻ sinh viên là làm miễn phí ngay nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Dạ đây ạ, làm xong thì một lần được mượn mấy quyển sách vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Du học sinh một lần được mượn mười quyển, thời hạn mượn là ba mươi ngày nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Hán này được không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để tôi quét mã đăng ký cho em, đã mượn thành công rồi nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn chị rất nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh ơi, email của trường em không đăng nhập được, mật khẩu ban đầu bị sai đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy à? Có phải em gõ sai chữ hoa chữ thường không đấy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Có thể lắm! Em cứ không để ý phân biệt chữ hoa chữ thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ cho, gõ lại phân biệt hoa thường là đăng nhập được thôi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Đăng nhập được rồi! Vậy tiếp theo đổi mật khẩu như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào phần cài đặt cá nhân đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ vâng, em đổi ngay đây, cảm ơn anh nhiều nha!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng ạ, em nộp bài trên nền tảng học tập mà cứ nộp không được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là do file không tải lên được, hay là trang bị lag vậy em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ load mãi, em bấm nộp mà không thấy phản hồi gì cả ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do tối nay hệ thống nền tảng bị nghẽn, hôm nay nhiều bạn cũng gặp tình trạng này rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị trừ điểm vì trễ hạn không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, do lỗi hệ thống nên hạn nộp sẽ được lùi lại cho tất cả, mai sáng nộp lại là được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','Tuyệt quá, cảm ơn trợ giảng đã báo cho em biết ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào thầy/cô ạ, em muốn hỏi về phạm vi chi trả của bảo hiểm y tế dành cho lưu học sinh ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Được thôi, bảo hiểm của trường chủ yếu chi trả chi phí khám ngoại trú và nội trú tại các bệnh viện công lập nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh thông thường như cảm cúm, viêm dạ dày ruột cũng được chi trả đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được nhé, các bệnh thông thường đều nằm trong phạm vi chi trả, kể cả tai nạn thương tích cũng được bồi thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Vậy có những khoản nào không được chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn thầy/cô đã giải thích chi tiết!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào chị/anh ạ, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi làm thủ tục thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự phục vụ trước, rồi điền vào phiếu thông tin cá nhân này nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Dạ vâng, quốc tịch và loại giấy tờ trong phiếu cứ điền đúng sự thật là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng rồi, điền hết thông tin cho chính xác, tránh để phiếu khám bị sai đó em.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền phiếu xong rồi, số cũng lấy rồi, tiếp theo làm gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Em cầm phiếu đi khám lần lượt các mục là được, quy trình đơn giản lắm nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi ạ, cảm ơn chị/anh!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu ơi, nói cậu biết, phía trước đường chính giờ cao điểm sáng đang kẹt cứng cả tuyến, xe chạy chậm lắm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác ơi, sáng nay em có tiết chuyên ngành, còn mười phút nữa là vào học rồi, kẹt thế này chắc chắn trễ mất!','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình đường sá, ba làn đường chính đều bị kẹt cứng, khó mà thông trong thời gian ngắn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không ạ, miễn sao kịp đến trường trước giờ học là được?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Có một con đường nhỏ trong khu dân cư đi vòng được, chỉ có điều xa hơn khoảng hai cây số thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng xa thêm chút cũng được, miễn đừng trễ học là được, phiền bác đi vòng giúp em nhé!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng trong đó nhiều người đi bộ, xe điện, tốc độ không nhanh được, chỉ chạy đều đều thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được kẹt xe dài trên đường chính là em thấy ổn rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, tôi chuyển làn xuống cầu vượt ngay bây giờ, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Chắc còn khoảng mấy phút nữa là tới cổng trường ạ, để em còn biết mà tính giờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Suôn sẻ thì bảy tám phút là tới, nhanh hơn đứng đợi tại chỗ đến hai chục phút đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ mà mất điểm chuyên cần rồi, cảm ơn bác đã cố tình đi vòng giúp em!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, sinh viên đi học là quan trọng, tôi cố gắng lái êm để không làm chậm trễ cậu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em sẽ đánh giá năm sao cho bác, thật sự cảm ơn bác nhiều lắm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng ba mươi tám tệ, phiền chị thanh toán giúp ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Vâng, em trả tiền mặt được không chị? Em không mang điện thoại để quét mã ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi em nha, cửa hàng bây giờ không nhận tiền mặt, chỉ nhận quét mã WeChat hoặc Alipay thôi.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Vậy à, để em mở điện thoại quét mã ngay đây ạ.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, em cứ từ từ, thanh toán xong chị xuất hóa đơn cho.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Em trả xong rồi ạ, cảm ơn chị đã nhắc!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào không thấy phản ứng gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô qua xem thử nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Vâng ạ, con thử hai lần rồi mà không được, quần áo bỏ vào không giặt được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này đang bị trục trặc tạm thời, con qua dùng cái máy bên cạnh là được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Dạ vâng, vậy máy hỏng bao giờ thì sửa xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai có thợ đến kiểm tra sửa chữa, tối nay con dùng tạm máy khác nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô quá, cảm ơn cô ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Dạ, xin lỗi làm phiền chị ạ! Em hình như đi nhầm chiều tàu điện ngầm rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu em, đừng lo, em định đi đâu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đến khu Đại học thành, vừa nãy lên nhầm chiều tàu ngược lại, giờ em không biết đổi tuyến thế nào ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ga tiếp theo, sang sân ga đối diện đi tuyến số 2 là đến thẳng nơi luôn nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Dạ, vậy em không cần mua vé lại đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi tuyến trong ga đều miễn phí, em cứ yên tâm đi nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Em cảm ơn chị nhiều lắm, thật sự giúp em một việc lớn luôn!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì đâu, lần sau nhớ xem kỹ chiều trước khi lên tàu nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, có phải Nguyễn Minh không? Hàng thu tiền hộ của bạn đến rồi nè, là chăn ga và đồ dùng nhà bếp đúng không?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền bạn kiểm tra thông tin giúp mình nha! Số điện thoại đuôi 3621 đúng không nhỉ?','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng luôn! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Cước phí tổng cộng 28 tệ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Trên app mình xem dự tính là 22 tệ mà, sao lại thêm 6 tệ vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn quá cân rồi, phần vượt cân phải trả thêm cước, app dự tính không chính xác đâu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, không sao, để mình quét mã trả tiền nha.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được đó! Trả xong mình ký nhận cho bạn, đồ đạc còn nguyên vẹn hết, bạn kiểm tra thử xem.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu, cảm ơn bạn đã vất vả chạy một chuyến!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Em ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Dì ơi, cháu lấy một suất cơm trứng xào cà chua ạ, cảm ơn dì!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi! Có muốn thêm món kèm không? Rau xanh với khoai tây đều tươi lắm.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Thôi khỏi ạ dì ơi! Phiền dì nhất định đừng cho cay nha, cháu hoàn toàn không ăn cay được.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Dì nhớ rồi, dì làm kiểu thanh đạm cho cháu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, cảm ơn dì nhiều!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ mà! Chút xíu là xong, cháu đợi một chút nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Anh Vũ ơi, mấy hôm nay em thấy hơi khó chịu, em muốn nói với anh một chuyện.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, khó chịu trong người à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là thủy thổ bất phục, tối cứ ngủ không ngon, ban ngày học thì buồn ngủ kinh khủng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay em ít nói hẳn! Vậy em định làm sao đây?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em muốn chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Đương nhiên không vấn đề gì! Em cứ nghỉ ngơi cho khỏe, tối anh nói khẽ lại, không làm phiền em đâu.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự làm phiền anh quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì, bạn cùng phòng vốn dĩ phải chăm sóc lẫn nhau mà.','AM09');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Dì Vương ơi, làm phiền dì rồi ạ! Cháu muốn hỏi thăm về quy định khách vào trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào cháu, có bạn muốn đến ký túc tìm cháu à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng ạ, bạn học của cháu mai muốn đến ký túc tìm cháu, cần đăng ký như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang theo chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy buổi tối có được đến thăm không ạ? Cháu vốn hẹn gặp vào tối cơ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Tối thì không được đâu, ký túc khóa cửa lúc mười giờ, ban đêm cấm người ngoài vào trường.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Ra là vậy, vậy cháu đổi sang ban ngày ạ, cảm ơn dì đã cho cháu biết!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không có gì, sắp xếp trước là được rồi, nhớ bảo bạn cháu mang theo giấy tờ nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi vì đã làm phiền anh nghỉ ngơi, có việc cần trao đổi và điều chỉnh với anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ mình đã hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em thật sự xin lỗi ạ! Chuyến bay nhập cảnh của em bị delay diện rộng, giờ hạ cánh lùi lại sáu tiếng, hôm nay chắc chắn em không kịp đến được rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Anh đã đặc biệt để trống cả buổi chiều nay ở nhà đợi em bàn giao, thay đổi đột xuất thế này quả thật hơi phiền.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói sớm nhất phải hai giờ chiều mai em mới đến được trung tâm thành phố.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay bàn giao xong phòng, tối còn ra ngoài có việc, giờ lịch trình bị đảo lộn hết cả rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em lùi lại một ngày nhận phòng được không, chiều mai em đến đúng giờ, tuyệt đối không trễ nữa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo lẽ thường phòng đã giữ trong ngày chỉ được giữ đến hết đêm hôm đó, muốn giữ qua đêm thì phải trả thêm phí nửa ngày để trống phòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định ạ, chỉ cần giữ được phòng thì phí liên quan em sẵn sàng chi trả bình thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang cũng không dễ dàng gì, phí để trống phòng anh sẽ không thu, nhưng hôm nay anh sẽ không giữ riêng phòng cho em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Em cảm ơn anh rất nhiều vì đã thông cảm và hiểu cho em, việc thay đổi lịch trình đột xuất đã làm phiền anh không ít, em thật sự xin lỗi!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo, đi xa khó tránh khỏi có chuyện phát sinh mà, nhưng trước khi đến vào ngày mai một tiếng thì nhất định phải báo trước cho anh một tiếng.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo trước cho anh giờ em đến, để anh tiện về nhà đợi sớm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy mình hẹn hai giờ chiều mai làm thủ tục nhận phòng, mai gặp nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này bao nhiêu tiền một thùng ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay bên chị đang có chương trình khuyến mãi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy là ưu đãi gì ạ, có lời không chị?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng thì giảm thẳng 20 tệ, lời lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế em mua hai thùng luôn, bình thường em uống nhiều mà.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được đó, để chị quét mã cho em, tính tiền sẽ tự động trừ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ vâng, cảm ơn chị nhé!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Dì ơi, cho cháu hỏi rau củ quả là cân ở đây đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi đó, đặt đồ lên rồi chọn đúng tên rau là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ thật, cháu bấm mấy lần rồi mà sao không ra tem nhỉ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để dì xem, cháu chọn cải thảo mà lại cầm cải xanh, chọn sai loại rồi kìa.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Ra là vậy, thảo nào cứ không được, để cháu làm lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, từ từ thôi, dán tem xong là ra máy tự thanh toán được rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Cháu cảm ơn dì nhiều lắm, không thì cháu chắc kẹt ở đây lâu lắm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào chị, sản phẩm của em bị lỗi chất lượng, em muốn đến quầy hậu mãi để đổi trả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào em, phiền em nói cho chị biết là sản phẩm gì, mua trong cửa hàng lúc nào vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Là một ổ bánh mì sandwich nguyên cám ạ, em mua chiều tối hôm qua ở khu bánh tươi, sáng nay mở ra thì đã bị mốc rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền em cho chị xem hóa đơn mua hàng tương ứng, bên chị cần đối chiếu thời gian mua và thông tin lô hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn giữ cẩn thận trong ví, giờ em đưa chị đây, em bảo quản ở nhiệt độ thường suốt, cũng có để lâu đâu ạ.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Chị đối chiếu với ghi chép nhập kho trong hệ thống theo lô bánh, xác nhận là do khâu bảo quản của nhà sản xuất có vấn đề, chị thật sự xin lỗi em.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao ạ, em cũng không cố tình làm khó cửa hàng đâu, chỉ là lo khách khác cũng mua phải hàng cùng loại thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Em muốn đổi sản phẩm mới, hay là xin hoàn tiền toàn bộ, cả hai phương án đều thực hiện được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám chọn lại nữa, hoàn tiền toàn bộ trực tiếp sẽ hợp lý hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, chị xử lý hoàn tiền trên hệ thống ngay đây, tiền sẽ hoàn về đúng theo phần mềm thanh toán em đã dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Tiền hoàn về khoảng bao lâu ạ, có bị chậm trễ không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền thanh toán trực tuyến là về ngay lập tức, giờ em mở điện thoại lên là thấy số dư thay đổi liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_13','V303','阮明',13,'清楚流程了，给您添麻烦实在不好意思。','qīng chǔ liú chéng le， gěi nín tiān má fán shí zài bù hǎo yì sī。','Em rõ quy trình rồi ạ, làm phiền chị quá, em thật sự ngại quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_14','V303','店员',14,'是我们商品存在质量瑕疵，本该向您致歉，您慢走。','shì wǒ men shāng pǐn cún zài zhì liàng xiá cī， běn gāi xiàng nín zhì qiàn， nín màn zǒu。','Là do sản phẩm bên chị có lỗi chất lượng, đáng lẽ chị phải xin lỗi em mới đúng, em đi cẩn thận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_15','V303','阮明',15,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Dạ vâng, phiền chị nhiều nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Anh ơi, em là sinh viên mới, em muốn mua một bộ chăn ga gối ký túc với cả nồi nấu nhỏ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có chứ, mấy món này đều là hàng chuyên dùng cho sinh viên, độ dày với công suất đều hợp với ký túc hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không anh? Em sợ lạnh lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ ấm qua đông luôn, chỉ có điều nồi nấu nhỏ trong ký túc hôm nay vừa bán hết hàng mất rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy khi nào có hàng lại ạ? Em cần gấp lắm.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai hàng về, mai em qua lấy là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Được ạ, vậy hôm nay em mua chăn, gối với ly nước trước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào dùng tốt vậy? Đây là lần đầu em giặt đồ ở ký túc xá.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại chai này là được nè, mùi nhẹ nhàng, tẩy vết bẩn cũng ổn lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Dạ được, vậy cái máy giặt tự động ở tầng dưới có khó dùng không chị?','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó tí nào đâu, quét mã thanh toán, bỏ đồ với nước giặt vào là xong à.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Em có cần tự chỉnh thời gian với chế độ giặt không?',NULL);
